def test_add_credit_writes_one_audit_log_per_ledger_entry(
    self, _name: str, duplicate: bool, already_logged: bool
) -> None:
    if already_logged:
        ActivityLog.objects.create(
            team_id=self.team.id, scope="AIGatewayCredit", activity="credit_added", item_id="e1"
        )
    result = CreditResult(
        team_id=self.team.id, entry_id="e1", amount_usd="5.000000", balance_usd="15.000000", duplicate=duplicate
    )
    with patch("posthog.admin.admins.team_admin.add_credit", return_value=result):
        self.admin.add_ai_gateway_credit_view(self._post({"amount_usd": "5", "reason": "promo"}), str(self.team.pk))

    logs = ActivityLog.objects.filter(team_id=self.team.id, scope="AIGatewayCredit", item_id="e1")
    assert logs.count() == 1
    if already_logged:
        return
    log = logs.get()
    assert log.activity == "credit_added"
    assert log.user == self.user
    assert log.was_impersonated is False
    assert log.detail["context"] == {"amount_usd": "5.000000", "reason": "promo", "balance_usd": "15.000000"}

